 "content": "def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # Find full-width horizontal and full-height vertical separators.
    rs=[r for r in range(h) if len(set(g[r]))==1 and g[r][0]!=0]
    cs=[c for c in range(w) if all(g[r][c]==g[0][c] and g[0][c]!=0 for r in range(h))]
    rb=[-1]+rs+[h]; cb=[-1]+cs+[w]
    bands=[(a+1,b) for a,b in zip(rb,rb[1:]) if b>a+1]
    panels=[(a+1,b) for a,b in zip(cb,cb[1:]) if b>a+1]
    for r0,r1 in bands:
      for k in range(0,len(panels)-1,2):
        (c0,c1),(d0,d1)=panels[k],panels[k+1]
        # Pair is a horizontal mirror correspondence; left panel is canonical
        # when present, otherwise reflect right into left.
        left=[[(g[r][c] if g[r][c] not in (0,8) else 0) for c in range(c0,c1)] for r in range(r0,r1)]
        right=[[(g[r][c] if g[r][c] not in (0,8) else 0) for c in range(d0,d1)] for r in range(r0,r1)]
        hasL=any(v for row in left for v in row); hasR=any(v for row in right for v in row)
        if hasL:
          for i in range(r1-r0):
            for j in range(d1-d0):
              g[r0+i][d0+j]=left[i][(c1-c0)-1-j] if j < (c1-c0) else 0
        elif hasR:
          for i in range(r1-r0):
            for j in range(c1-c0):
              g[r0+i][c0+j]=right[i][(d1-d0)-1-j] if j < (d1-d0) else 0
    return g
"
}

